function outer(a, ...rest) {
  const peek = () => arguments.length;
  const grab = (...args) => args.length;
  rest.push("extra");

  return `${peek(1)} ${grab(1)} ${rest.length} ${Array.isArray(arguments)}`;
}

function swap(a, b) {
  [a, b] = [b, a];

  return `${a}${b} ${arguments[0]}${arguments[1]}`;
}

console.log(outer("x", "y", "z"));
console.log(outer());
console.log(swap("p", "q"));
